2	
3	import java.util.regex.Pattern;
4	import org.springframework.web.bind.annotation.RequestBody;
5	import net.officefloor.server.http.HttpException;
6	import net.officefloor.server.http.HttpStatus;
7	import net.officefloor.web.ObjectResponse;
8	
9	/**
10	 * {@code POST /api/contacts} — create a contact from a {clientId, name, email, role} body and return
11	 * the saved row (with its generated id). Wired by {@code officefloor/rest/api/contacts.POST.yml}. A
12	 * contact must belong to an existing client: the clientId is validated here and rejected with 400
13	 * before it reaches the repository (the DB foreign key in Flyway V10 is the matching last line of
14	 * defence). Name, email and role are required.
15	 */
16	public class ContactsPostLogic {
17	
18	    /** A proper email address: local part, @, and a domain with a dot — no whitespace. */
19	    private static final Pattern EMAIL = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
20	
21	    public void service(@RequestBody NewContact newContact, ContactRepository contacts,
22	            ClientRepository clients, ObjectResponse<Contact> response) {
23	        Long clientId = newContact.getClientId();
24	        String name = newContact.getName();
25	        String email = newContact.getEmail();
26	        String role = newContact.getRole();
27	        if (clientId == null || !clients.existsById(clientId)) {
28	            throw new HttpException(HttpStatus.BAD_REQUEST, "A valid client is required");
29	        }
30	        if (name == null || name.trim().isEmpty()) {
31	            throw new HttpException(HttpStatus.BAD_REQUEST, "A contact name is required");
32	        }
33	        if (email == null || !EMAIL.matcher(email.trim()).matches()) {
34	            throw new HttpException(HttpStatus.BAD_REQUEST, "A proper contact email address is required");
35	        }
36	        if (role == null || role.trim().isEmpty()) {
37	            throw new HttpException(HttpStatus.BAD_REQUEST, "A contact role is required");
38	        }
39	        Contact saved = contacts.save(
40	                new Contact(clientId, name.trim(), email.trim(), role.trim()));
41	        response.send(saved);
42	    }
43	
44	    /** Request body for creating a contact. */
45	    public static class NewContact {
46	        private Long clientId;
47	        private String name;
48	        private String email;
49	        private String role;
50	
