  return useMutation({
    mutationFn: (input: { text: string }) =>
      postJson<Note>('/api/notes', {
        targetType: 'project',
        targetId: projectId,
        text: input.text,
      }),
    onSuccess: () =>
      queryClient.invalidateQueries({ queryKey: projectNotesKey(projectId) }),
  });
}

